window.addEventListener('message',async e=>{if(e.origin!==location.origin||!['explorer-open','explorer-new','office-launch','app-ready','app-failed','explorer-ready','explorer-close','app-close','explorer-changed','explorer-shortcut'].includes(e.data?.type))return;const source=[...document.querySelectorAll('.independent-app-window>iframe')].find(f=>f.contentWindow===e.source);if(!source)return;if(e.data.type==='office-launch'){if(!['text','sheet','presentation'].includes(e.data.kind))return;let node=e.data.id?get(e.data.id):null;if(e.data.id&&!node){await load();node=get(e.data.id);}if(!e.data.id||node)openOffice(node,e.data.kind);return;}if(e.data.type==='explorer-shortcut'){await load();const node=get(e.data.id);if(node)await shell?.createShortcut(node);return;}if(e.data.type==='explorer-changed'){await load();return;}if(e.data.type==='explorer-ready'||e.data.type==='app-ready'){source.style.visibility='visible';source.parentElement.querySelector('.app-loading')?.remove();return;}if(e.data.type==='app-failed'){const label=source.parentElement.querySelector('.app-loading span');if(label)label.textContent='Die Anwendung konnte nicht geladen werden. Bitte schließen und erneut öffnen.';return;}if(e.data.type==='explorer-close'||e.data.type==='app-close'){source.closest('dialog').close();return;}if(e.data.type==='explorer-new'){launchInstance('explorer',get(e.data.id)||get(current));return;}let node=get(e.data.id);if(!node){await load();node=get(e.data.id);}if(node){if(e.data.paint===true){paintApp.open(node);return;}if(e.data.edit===true&&state.authenticated)openText(node,true);else open(node);}});
