const securityClientId=crypto.randomUUID();let securityLastUsed=Date.now();for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>securityLastUsed=Date.now(),{passive:true});
const desktopSecurityChannel=!isolatedApp&&typeof BroadcastChannel==='function'?new BroadcastChannel('windows7-security'):null;
desktopSecurityChannel?.addEventListener('message',async e=>{const data=e.data;if(!state.authenticated||state.shareEditing||data?.userId!==state.userId)return;if(data.type==='find-desktop')desktopSecurityChannel.postMessage({type:'desktop-offer',requestId:data.requestId,clientId:securityClientId,lastUsed:securityLastUsed});if(data.type==='lock-desktop'&&data.target===securityClientId){const ok=await lockWorkspace();desktopSecurityChannel.postMessage({type:'lock-result',requestId:data.requestId,ok:!!ok});}});
async function captureWorkspace(onlyId){const items=[];for(const app of desktop.applications().filter(app=>!onlyId||app.id===onlyId).sort((a,b)=>Number($(a.id)?.style.zIndex)-Number($(b.id)?.style.zIndex))){const dialog=$(app.id);let value;if(dialog.workspaceState)value=await dialog.workspaceState();else if(editorWindows.has(app.id)){const r=editorWindows.get(app.id);value={type:'editor',id:r.node.id,name:r.node.name,content:r.field.value,original:r.original,version:r.version,readOnly:r.field.readOnly,selection:r.editor.view.state.selection.main.head,anchor:r.editor.view.state.selection.main.anchor,scrollLeft:r.editor.view.scrollDOM.scrollLeft,scroll:r.editor.view.scrollDOM.scrollTop};}else if(app.id==='explorer-window')value={type:'explorer',folder:current,details};else if(app.appId==='task-manager')value={type:'task-manager',tab:dialog.querySelector('[role=tab][aria-selected=true]')?.dataset.taskTab};else if(app.appId==='local-users')value={type:'local-users'};else if(app.appId==='accounts')value={type:'accounts'};else if(app.appId==='display-settings')value={type:'display-settings'};else if(app.id==='documentviewer')value={type:'document',id:documentNode?.id};else if(app.id==='trash-window')value={type:'trash'};else throw Error('Arbeitsstand von „'+app.title+'“ kann noch nicht gesichert werden. Bitte dieses Fenster zuerst schließen.');items.push({...value,geometry:desktop.workspaceGeometry(app.id)});}return {version:1,items};}
let lockingWorkspace=false;async function lockWorkspace(){if(!state.authenticated||state.shareEditing||lockingWorkspace)return;lockingWorkspace=true;showBusy('Arbeitsstand wird gesichert …','Der Computer wird anschließend gesperrt.');try{const localSnapshot=await captureWorkspace(),snapshot=screens?await screens.collect(localSnapshot):localSnapshot;await api('/api/workspace-lock',snapshot);screens?.seal();for(const p of document.querySelectorAll('audio,video'))p.pause();workspaceLeaving=true;const username=state.username;showBusy('Computer wird gesperrt …');location.replace('/login?locked='+encodeURIComponent(username));return true;}catch(error){hideBusy();toast('Nicht gesperrt: '+error.message);return false;}finally{lockingWorkspace=false;}}
async function restoreWorkspace(override){const saved=override||await api('/api/workspace');if(!saved?.items?.length)return;for(const item of saved.items){try{let dialog;if(item.type==='minesweeper'){dialog=minesweeperApp.open(item);await dialog.whenReady;}else if(item.type==='nibbles'){dialog=nibblesApp.open(item);await dialog.whenReady;}else if(item.type==='paint'){const restored=paintApp.open(item.nodeId?get(item.nodeId):null,item);await restored.whenReady;dialog=restored.el;}else if(item.type==='snipping'){dialog=snippingApp.open(item);await dialog.whenReady;}else if(item.type==='editor'){const n=item.id?get(item.id):null;if(item.id&&!n)throw Error('Datei nicht mehr verfügbar: '+item.name);const fresh=n?await api('/api/text?id='+n.id):{writable:true,encoding:'utf8'};const r=await createTextWindow(n||{id:null,name:item.name,kind:'file'},{...fresh,content:item.content,version:item.version},!item.readOnly);r.original=item.original;r.version=item.version;r.field.value=item.original??item.content;r.editor.view.dispatch({changes:{from:0,to:r.editor.view.state.doc.length,insert:item.content}});r.editor.view.dispatch({selection:{anchor:Math.min(item.anchor??item.selection??0,r.editor.view.state.doc.length),head:Math.min(item.selection||0,r.editor.view.state.doc.length)}});r.editor.view.scrollDOM.scrollTop=item.scroll||0;r.editor.view.scrollDOM.scrollLeft=item.scrollLeft||0;dialog=r.el;}else if(item.type==='instance'){dialog=launchInstance(item.app);const frame=dialog.querySelector('iframe');await new Promise((resolve,reject)=>{const start=Date.now(),timer=setInterval(async()=>{if(frame.contentWindow?.workspaceReady){clearInterval(timer);try{await frame.contentWindow.restoreInnerWorkspace(item.state);resolve();}catch(e){reject(e);}}else if(Date.now()-start>30000){clearInterval(timer);reject(Error('App startet zu langsam.'));}},50);});}else if(item.type==='explorer'){if(get(item.folder))go(item.folder,false);details=!!item.details;desktop.show('explorer-window');dialog=$('explorer-window');}else if(item.type==='terminal'){terminalApp.open();dialog=$('terminal-window');dialog.restoreWorkspace(item);}else if(item.type==='task-manager'){taskManager.open();dialog=$('taskmanager');dialog.querySelector('[data-task-tab="'+item.tab+'"]')?.click();}else if(item.type==='display-settings'){screens.open();dialog=$('control-panel');}else if(item.type==='control-panel'){controlPanel.open(item.page);dialog=$('control-panel');}else if(item.type==='accounts'){await accounts.open();dialog=$('control-panel');}else if(item.type==='document'&&get(item.id)){await open(get(item.id));dialog=$('documentviewer');}else if(item.type==='local-users'&&state.role==='admin'){localUserManagement.open();dialog=$('local-users-management');}else if(item.type==='link'){const n=get(item.id);if(n)openLink(n,item);else if(item.id==='browser')openLink({id:'browser',name:'Internet Explorer',url:BROWSER_HOME,openInWindow:true},item);dialog=[...linkWindows.values()].at(-1);}else if(item.type==='office-file'){const n=get(item.id);if(n)dialog=openOffice(n,item.kind);}else if(item.type==='trash'){await trash.open();dialog=$('explorer-window');}else if(item.type==='office'){const draft=await api('/api/office-resume',{id:item.checkpoint});dialog=openOffice(draft,item.kind,{dirty:item.dirty});}if(dialog&&item.geometry)desktop.applyWorkspaceGeometry(dialog.id,item.geometry);}catch(error){if(override)throw error;toast('Wiederherstellung: '+error.message);}}if(!override&&!secondaryScreen)window.history.replaceState({},'','/');}


const screens=!isolatedApp?createScreens({desktop,getState:()=>state,api,reload:()=>load(),capture:captureWorkspace,restore:restoreWorkspace,isSecondary:secondaryScreen,toast,showBusy,closeTransferred:id=>{const r=editorWindows.get(id);if(r)r.original=r.field.value;document.getElementById(id)?.close();}}):null;screens?.setHost(()=>controlPanel.open('display'));window.openDisplaySettings=()=>screens?.open();

function visibleIds(){return [...$('list').querySelectorAll('.item')].map(el=>el.dataset.id);}
function paintSelection(){const visible=visibleIds();for(const id of selection)if(!get(id))selection.delete(id);if(!selection.has(selected))selected=[...selection].at(-1)||null;for(const el of $('list').children){el.classList.toggle('selected',selection.has(el.dataset.id));el.classList.toggle('cut',cutIds.includes(el.dataset.id));el.setAttribute('aria-selected',String(selection.has(el.dataset.id)));}if(selection.size>1){updateStatus(null,visible.length);$('count').textContent=selection.size+' Elemente ausgewählt';}else updateStatus(get(selected),visible.length);}
function selectItem(n,e,items){if(e.shiftKey&&selectionAnchor){const ids=items.map(x=>x.id),a=ids.indexOf(selectionAnchor),b=ids.indexOf(n.id);if(!e.ctrlKey&&!e.metaKey)selection.clear();if(a>=0)for(const id of ids.slice(Math.min(a,b),Math.max(a,b)+1))selection.add(id);else selection.add(n.id);}else if(e.ctrlKey||e.metaKey){selection.has(n.id)?selection.delete(n.id):selection.add(n.id);selectionAnchor=n.id;}else{selection.clear();selection.add(n.id);selectionAnchor=n.id;}selected=n.id;paintSelection();}
function moveRoots(ids){const all=new Set(ids);return [...all].filter(id=>{let p=get(id)?.parent;const seen=new Set();while(p&&!seen.has(p)){if(all.has(p))return false;seen.add(p);p=get(p)?.parent;}return true;});}
function movableIds(){return moveRoots([...selection].filter(id=>{const n=get(id);return n&&!n.virtual&&!n.system;}));}
function cutSelection(){const ids=movableIds();if(!state.authenticated||!ids.length)return;cutIds=ids;copyIds=[];saveClipboard('cut',ids);paintSelection();toast(ids.length+' Element'+(ids.length===1?'':'e')+' ausgeschnitten · Im Zielordner einfügen');}
function dropFolder(id){if(!state.authenticated)return null;if(id==='@home')return '@home';const n=get(id);if(!n||n.kind!=='folder'||n.writable===false)return null;if(!n.virtual)return id;if(['@desktop','@downloads','@documents','@music','@pictures','@videos'].includes(id))return nodes.find(x=>x.system&&x.space===id.slice(1))?.id||null;return null;}
function canDrop(ids,targetId){const target=dropFolder(targetId);if(!ids.length||!target)return false;const normalized=moveRoots(ids);return normalized.every(id=>{const n=get(id);if(!n||n.system||n.virtual||n.desktopShortcut)return false;let p=target;const seen=new Set();while(p&&!seen.has(p)){if(p===id)return false;seen.add(p);p=get(p)?.parent;}return true;})&&normalized.some(id=>get(id)?.parent!==target);}
async function transferSelection(ids,parent,mode){const roots=moveRoots(ids),progress=transferDialog({verb:mode==='copy'?'Kopieren':'Verschieben',count:roots.length,from:get(get(roots[0])?.parent)?.name||'Desktop',to:get(parent)?.name||'Desktop'}),done=[];try{for(const id of roots){if(progress.cancelled)break;progress.update({name:get(id)?.name||'',completed:done.length,busy:true,byteMode:false});if(mode==='copy')await copyWithProgress({ids:[id],parent},event=>progress.update({name:event.name,byteMode:event.totalBytes>0,totalBytes:event.totalBytes,loaded:event.loadedBytes}),progress);else await api('/api/'+mode,{ids:[id],parent});done.push(id);progress.update({completed:done.length,busy:false});}return {done,cancelled:progress.cancelled};}catch(error){error.completedIds=done;throw error;}finally{progress.close();}}
async function moveSelection(ids,targetId){const target=dropFolder(targetId);if(!canDrop(ids,targetId))return toast('Bitte einen anderen gültigen Zielordner auswählen.');let done=[];try{const result=await transferSelection(ids,target,'move');done=result.done;toast(result.cancelled?'Verschieben abgebrochen. Fertige Elemente bleiben im Ziel.':done.length+' Element(e) verschoben');return !result.cancelled;}catch(error){done=error.completedIds||[];toast(error.message);return false;}finally{cutIds=cutIds.filter(id=>!done.includes(id));const clip=readClipboard();if(clip.mode==='cut')saveClipboard('cut',clip.ids.filter(id=>!done.includes(id)));selection.clear();selected=null;await load();}}
function saveClipboard(mode,ids){try{sessionStorage.setItem('windows7.clipboard',JSON.stringify({owner:state.userId,mode,ids}));}catch{}}
function readClipboard(){try{const value=JSON.parse(sessionStorage.getItem('windows7.clipboard'));if(value?.owner===state.userId&&Array.isArray(value.ids))return value;}catch{}return {mode:typeof copyIds!=='undefined'&&copyIds.length?'copy':'cut',ids:typeof copyIds!=='undefined'&&copyIds.length?copyIds:cutIds};}
function clipboardIds(){return readClipboard().ids;}
function copySelection(){const ids=movableIds();if(!state.authenticated||!ids.length)return;copyIds=ids;cutIds=[];saveClipboard('copy',ids);paintSelection();toast(ids.length+' Element(e) kopiert');}
async function pasteSelection(id=current){const clip=readClipboard(),parent=dropFolder(id);if(!state.authenticated||!parent||!clip.ids.length)return;if(clip.mode==='copy'){try{const result=await transferSelection(clip.ids,parent,'copy');toast(result.cancelled?'Kopieren abgebrochen. Fertige Elemente bleiben im Ziel.':result.done.length+' Element(e) kopiert');}catch(error){toast(error.message);}finally{await load();}}else await moveSelection(clip.ids,id);}

async function deleteSelection(){const ids=movableIds();if(!ids.length)return;if(ids.length===1)return deleteNode(get(ids[0]));if(!await confirmAction(ids.length+' ausgewählte Elemente in den Papierkorb verschieben?'))return;try{const shortcuts=ids.filter(id=>get(id)?.desktopShortcut);if(shortcuts.length)await recycleDesktopShortcuts(shortcuts);for(const id of ids.filter(id=>!shortcuts.includes(id)))await api('/api/delete',{id});selection.clear();selected=null;await load();}catch(e){await load();toast(e.message);}}
function resetDragHover(){clearTimeout(dragHoverTimer);dragHoverTimer=null;dragHoverId=null;document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));}
function wireDragSource(el,n){el.draggable=!!state.authenticated&&!n.virtual&&!n.system;el.addEventListener('dragstart',e=>{if(!el.draggable)return;if(!selection.has(n.id)){selection.clear();selection.add(n.id);selected=n.id;paintSelection();}dragIds=movableIds();if(!dragIds.length){e.preventDefault();return;}e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('application/x-explorer-nodes',JSON.stringify(dragIds));e.dataTransfer.setData('text/plain',dragIds.map(id=>get(id).name).join(', '));});el.addEventListener('dragend',()=>{dragIds=[];resetDragHover();});}
